import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const MAX_SIZE = 200;
const DEFAULT_SIZE = 20;

interface Db {
  query: (sql: string, params?: Record<string, unknown>) => Promise<any[]>;
  execute: (sql: string, params?: Record<string, unknown>) => Promise<number>;
}

interface ItemInput {
  budgetGroup: string;
  ioType: string;
  parentBudgetItemId: number | null;
  itemCode: string;
  itemName: string;
  isControlled: boolean;
  controlUnit: string | null;
  isTransferable: boolean;
  useStartDate: string | null;
  useEndDate: string | null;
  accountItemIds: number[] | null;
}

function invalid(message: string): ApiError {
  return new ApiError(422, 'BUDGET_ITEM_INPUT_INVALID', message);
}

function text(v: unknown, max: number, label: string): string {
  if (typeof v !== 'string' || v.trim() === '') {
    throw invalid(label + '을(를) 입력하세요.');
  }
  if (v.trim().length > max) {
    throw invalid(label + '은(는) ' + max + '자 이하로 입력하세요.');
  }
  return v.trim();
}

function optInt(v: unknown, label: string): number | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v !== 'number' || !Number.isInteger(v)) {
    throw invalid(label + '은(는) 정수여야 합니다.');
  }
  return v;
}

function optDate(v: unknown, label: string): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v)) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return v;
}

function bool(v: unknown, label: string): boolean {
  if (typeof v !== 'boolean') {
    throw invalid(label + '을(를) 선택하세요.');
  }
  return v;
}

function parseInput(data: Record<string, unknown>): ItemInput {
  const budgetGroup = text(data['budgetGroup'], 50, '예산그룹');
  const itemCode = text(data['itemCode'], 30, '예산과목 코드');
  const itemName = text(data['itemName'], 200, '예산과목 명칭');
  const ioType = data['ioType'];
  if (ioType !== '수입' && ioType !== '지출') {
    throw invalid('수입·지출 유형이 올바르지 않습니다.');
  }
  const isControlled = bool(data['isControlled'], '통제 여부');
  const isTransferable = bool(data['isTransferable'], '예산 전용 여부');
  let controlUnit: string | null = null;
  const cu = data['controlUnit'];
  if (cu !== undefined && cu !== null && cu !== '') {
    if (cu !== '월' && cu !== '분기' && cu !== '연') {
      throw invalid('통제 단위는 월·분기·연 중 하나여야 합니다.');
    }
    controlUnit = cu;
  }
  if (isControlled && controlUnit === null) {
    throw invalid('통제하는 과목은 통제 단위를 선택하세요.');
  }
  let accountItemIds: number[] | null = null;
  const raw = data['accountItemIds'];
  if (raw !== undefined && raw !== null) {
    if (!Array.isArray(raw)) {
      throw invalid('계정과목 ID 목록 형식이 올바르지 않습니다.');
    }
    const ids: number[] = [];
    for (const x of raw) {
      if (typeof x !== 'number' || !Number.isInteger(x)) {
        throw invalid('계정과목 ID는 정수여야 합니다.');
      }
      if (!ids.includes(x)) {
        ids.push(x);
      }
    }
    accountItemIds = ids;
  }
  return {
    budgetGroup,
    ioType,
    parentBudgetItemId: optInt(data['parentBudgetItemId'], '상위 예산과목 ID'),
    itemCode,
    itemName,
    isControlled,
    controlUnit,
    isTransferable,
    useStartDate: optDate(data['useStartDate'], '사용 시작일'),
    useEndDate: optDate(data['useEndDate'], '사용 종료일'),
    accountItemIds,
  };
}

async function validateRefs(db: Db, p: ItemInput, selfId: number | null): Promise<void> {
  if (p.useStartDate !== null && p.useEndDate !== null) {
    const r = await db.query(
      'SELECT (CAST(:e AS date) < CAST(:s AS date)) AS "bad"',
      { e: p.useEndDate, s: p.useStartDate },
    );
    if (r[0] && r[0].bad === true) {
      throw invalid('사용 종료일은 시작일보다 빠를 수 없습니다.');
    }
  }
  if (p.parentBudgetItemId !== null) {
    if (selfId !== null && p.parentBudgetItemId === selfId) {
      throw invalid('자기 자신을 상위 예산과목으로 지정할 수 없습니다.');
    }
    const r = await db.query(
      'SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:id AS bigint)',
      { id: p.parentBudgetItemId },
    );
    if (r.length === 0) {
      throw invalid('상위 예산과목이 존재하지 않습니다.');
    }
  }
  const dup = await db.query(
    'SELECT budget_item_id FROM budget_item WHERE item_code = :code AND (CAST(:self AS bigint) IS NULL OR budget_item_id <> CAST(:self AS bigint))',
    { code: p.itemCode, self: selfId },
  );
  if (dup.length > 0) {
    throw invalid('이미 사용 중인 예산과목 코드입니다.');
  }
  for (const id of p.accountItemIds ?? []) {
    const r = await db.query(
      'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:id AS bigint)',
      { id },
    );
    if (r.length === 0) {
      throw new ApiError(422, 'ACCOUNT_ITEM_INVALID', '존재하지 않는 계정과목은 매핑할 수 없습니다.');
    }
  }
}

async function replaceMaps(db: Db, itemId: number, ids: number[]): Promise<void> {
  await db.execute(
    'DELETE FROM budget_account_map WHERE budget_item_id = CAST(:itemId AS bigint)',
    { itemId },
  );
  for (const id of ids) {
    await db.execute(
      'INSERT INTO budget_account_map (budget_item_id, account_item_id, created_at, updated_at) ' +
        'VALUES (CAST(:itemId AS bigint), CAST(:id AS bigint), now(), now())',
      { itemId, id },
    );
  }
}

@Controller('api/v1')
export class FnSfr00203Controller {
  @Post('/budget-items')
  @HttpCode(200)
  async createBudgetItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    return transaction(async (db) => {
      const p = parseInput(data);
      await validateRefs(db, p, null);
      const rows = await db.query(
        'INSERT INTO budget_item (item_code, item_name, budget_group, io_type, parent_budget_item_id, ' +
          'is_controlled, control_unit, is_transferable, use_start_date, use_end_date, created_at, updated_at) ' +
          'VALUES (:itemCode, :itemName, :budgetGroup, :ioType, CAST(:parent AS bigint), ' +
          ':isControlled, :controlUnit, :isTransferable, CAST(:useStart AS date), CAST(:useEnd AS date), now(), now()) ' +
          'RETURNING budget_item_id AS "budgetItemId"',
        {
          itemCode: p.itemCode,
          itemName: p.itemName,
          budgetGroup: p.budgetGroup,
          ioType: p.ioType,
          parent: p.parentBudgetItemId,
          isControlled: p.isControlled,
          controlUnit: p.controlUnit,
          isTransferable: p.isTransferable,
          useStart: p.useStartDate,
          useEnd: p.useEndDate,
        },
      );
      const budgetItemId = Number(rows[0].budgetItemId);
      await replaceMaps(db, budgetItemId, p.accountItemIds ?? []);
      return { budgetItemId };
    });
  }

  @Put('/budget-items/:budgetItemId')
  async updateBudgetItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const idText = req.params['budgetItemId'];
    return transaction(async (db) => {
      if (!/^\d+$/.test(idText)) {
        throw new ApiError(404, 'BUDGET_ITEM_NOT_FOUND', '예산과목을 찾을 수 없습니다.');
      }
      const found = await db.query(
        'SELECT budget_item_id AS "budgetItemId" FROM budget_item WHERE budget_item_id = CAST(:id AS bigint)',
        { id: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'BUDGET_ITEM_NOT_FOUND', '예산과목을 찾을 수 없습니다.');
      }
      const budgetItemId = Number(found[0].budgetItemId);
      const p = parseInput(data);
      await validateRefs(db, p, budgetItemId);
      await db.execute(
        'UPDATE budget_item SET item_code = :itemCode, item_name = :itemName, budget_group = :budgetGroup, ' +
          'io_type = :ioType, parent_budget_item_id = CAST(:parent AS bigint), is_controlled = :isControlled, ' +
          'control_unit = :controlUnit, is_transferable = :isTransferable, ' +
          'use_start_date = CAST(:useStart AS date), use_end_date = CAST(:useEnd AS date), updated_at = now() ' +
          'WHERE budget_item_id = CAST(:id AS bigint)',
        {
          id: budgetItemId,
          itemCode: p.itemCode,
          itemName: p.itemName,
          budgetGroup: p.budgetGroup,
          ioType: p.ioType,
          parent: p.parentBudgetItemId,
          isControlled: p.isControlled,
          controlUnit: p.controlUnit,
          isTransferable: p.isTransferable,
          useStart: p.useStartDate,
          useEnd: p.useEndDate,
        },
      );
      if (p.accountItemIds !== null) {
        await replaceMaps(db, budgetItemId, p.accountItemIds);
      }
      return { budgetItemId };
    });
  }

  @Get('/budget-items')
  async listBudgetItems(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const pageNo = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const size = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(pageNo) || pageNo < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'page와 size 값이 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    const group = typeof query['budgetGroup'] === 'string' && query['budgetGroup'] !== '' ? String(query['budgetGroup']) : null;
    const io = typeof query['ioType'] === 'string' && query['ioType'] !== '' ? String(query['ioType']) : null;
    if (io !== null && io !== '수입' && io !== '지출') {
      throw new ApiError(400, 'VALIDATION_FAILED', '수입·지출 유형이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const where =
        'WHERE (CAST(:g AS text) IS NULL OR budget_group = CAST(:g AS text)) ' +
        'AND (CAST(:io AS text) IS NULL OR io_type = CAST(:io AS text))';
      const items = await db.query(
        'SELECT budget_item_id AS "budgetItemId", parent_budget_item_id AS "parentBudgetItemId", ' +
          'item_code AS "itemCode", item_name AS "itemName", budget_group AS "budgetGroup", io_type AS "ioType", ' +
          'is_controlled AS "isControlled", control_unit AS "controlUnit", is_transferable AS "isTransferable", ' +
          'CAST(use_start_date AS text) AS "useStartDate", CAST(use_end_date AS text) AS "useEndDate" ' +
          'FROM budget_item ' +
          where +
          ' ORDER BY budget_group, io_type, item_code LIMIT :limit OFFSET :offset',
        { g: group, io, limit, offset: pageNo * limit },
      );
      const cnt = await db.query('SELECT COUNT(*) AS "total" FROM budget_item ' + where, { g: group, io });
      return { items, page: pageNo, size: limit, total: Number(cnt[0].total) };
    });
  }
}

