import { useState } from 'react';
import { call, useData, Badge, DateText, Filters, DataTable, Pager, Drawer, Pairs, Tiles, Form, Field, TextInput, DateInput, Select, LookupSelect, RefName } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const IO_OPTIONS: [string, string][] = [['수입', '수입'], ['지출', '지출']];
const UNIT_OPTIONS: [string, string][] = [['월', '월'], ['분기', '분기'], ['연', '연']];
const YES_NO: [string, string][] = [['true', '예'], ['false', '아니오']];

function yesNo(v: unknown): string {
  return v === true ? '예' : '아니오';
}

function toBool(v: string): boolean | string {
  if (v === 'true') {
    return true;
  }
  if (v === 'false') {
    return false;
  }
  return '';
}

function ItemForm({ role, row, onDone }: { role: string; row?: Row; onDone: () => void }) {
  const editing = row !== undefined;
  const [budgetGroup, setBudgetGroup] = useState<string>(String(row?.budgetGroup ?? ''));
  const [ioType, setIoType] = useState<string>(String(row?.ioType ?? ''));
  const [parentId, setParentId] = useState<number | string>((row?.parentBudgetItemId as number | undefined) ?? '');
  const [itemCode, setItemCode] = useState<string>(String(row?.itemCode ?? ''));
  const [itemName, setItemName] = useState<string>(String(row?.itemName ?? ''));
  const [isControlled, setIsControlled] = useState<string>(row ? String(row.isControlled === true) : '');
  const [controlUnit, setControlUnit] = useState<string>(String(row?.controlUnit ?? ''));
  const [isTransferable, setIsTransferable] = useState<string>(row ? String(row.isTransferable === true) : '');
  const [useStartDate, setUseStartDate] = useState<string>(String(row?.useStartDate ?? ''));
  const [useEndDate, setUseEndDate] = useState<string>(String(row?.useEndDate ?? ''));
  const [accountIds, setAccountIds] = useState<number[]>([]);
  const [mapTouched, setMapTouched] = useState(false);
  const [picker, setPicker] = useState<number | string>('');

  function addAccount(v: number | string) {
    setPicker('');
    if (typeof v !== 'number') {
      return;
    }
    if (!accountIds.includes(v)) {
      setAccountIds([...accountIds, v]);
    }
    setMapTouched(true);
  }

  function removeAccount(id: number) {
    setAccountIds(accountIds.filter((x) => x !== id));
    setMapTouched(true);
  }

  async function submit() {
    if (!budgetGroup.trim() || !ioType || !itemCode.trim() || !itemName.trim() || !isControlled || !isTransferable) {
      throw new Error('필수 항목을 모두 입력하세요.');
    }
    if (isControlled === 'true' && !controlUnit) {
      throw new Error('통제하는 과목은 통제 단위를 선택하세요.');
    }
    if (useStartDate && useEndDate && useEndDate < useStartDate) {
      throw new Error('사용 종료일은 시작일보다 빠를 수 없습니다.');
    }
    const body: Row = {
      budgetGroup: budgetGroup.trim(),
      ioType,
      parentBudgetItemId: parentId === '' ? null : parentId,
      itemCode: itemCode.trim(),
      itemName: itemName.trim(),
      isControlled: toBool(isControlled),
      controlUnit: controlUnit || null,
      isTransferable: toBool(isTransferable),
      useStartDate: useStartDate || null,
      useEndDate: useEndDate || null,
    };
    if (!editing || mapTouched) {
      body.accountItemIds = accountIds;
    }
    if (editing) {
      await call('PUT', '/budget-items/' + String(row?.budgetItemId), role, body);
    } else {
      await call('POST', '/budget-items', role, body);
    }
    onDone();
  }

  return (
    <Form onSubmit={submit} submit={editing ? '수정' : '등록'}>
      <Field label="예산그룹" required>
        <TextInput value={budgetGroup} onChange={setBudgetGroup} />
      </Field>
      <Field label="수입·지출 유형" required>
        <Select value={ioType} onChange={setIoType} options={IO_OPTIONS} />
      </Field>
      <Field label="상위 예산과목 ID">
        <LookupSelect table="budget_item" role={role} value={parentId} onChange={setParentId} placeholder="최상위" />
      </Field>
      <Field label="예산과목 코드" required>
        <TextInput value={itemCode} onChange={setItemCode} />
      </Field>
      <Field label="예산과목 명칭" required>
        <TextInput value={itemName} onChange={setItemName} />
      </Field>
      <Field label="통제 여부" required>
        <Select value={isControlled} onChange={setIsControlled} options={YES_NO} />
      </Field>
      <Field label="통제 단위" hint="통제 여부가 예이면 필수">
        <Select value={controlUnit} onChange={setControlUnit} options={UNIT_OPTIONS} />
      </Field>
      <Field label="예산 전용 여부" required>
        <Select value={isTransferable} onChange={setIsTransferable} options={YES_NO} />
      </Field>
      <Field label="사용 시작일">
        <DateInput value={useStartDate} onChange={setUseStartDate} />
      </Field>
      <Field label="사용 종료일">
        <DateInput value={useEndDate} onChange={setUseEndDate} />
      </Field>
      <Field label="매핑할 계정과목 ID 목록" wide hint={editing ? '계정과목을 바꿀 때만 지정하세요. 지정하면 기존 매핑을 대체합니다.' : undefined}>
        <div>
          <LookupSelect table="account_item" role={role} value={picker} onChange={addAccount} placeholder="계정과목 추가" />
          {accountIds.map((id) => (
            <div key={id}>
              <RefName table="account_item" role={role} value={id} />
              <button type="button" onClick={() => removeAccount(id)}>제거</button>
            </div>
          ))}
        </div>
      </Field>
    </Form>
  );
}

export default function FnSfr00203Page({ role, notify }: PageProps) {
  const [group, setGroup] = useState('');
  const [io, setIo] = useState('');
  const [applied, setApplied] = useState<{ group: string; io: string }>({ group: '', io: '' });
  const [pageNo, setPageNo] = useState(0);
  const [drawer, setDrawer] = useState<{ row?: Row } | null>(null);
  const [detail, setDetail] = useState<Row | null>(null);
  const size = 20;

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/budget-items', role, undefined, { budgetGroup: applied.group, ioType: applied.io, page: pageNo, size }),
    [role, applied.group, applied.io, pageNo],
  );

  function search() {
    setPageNo(0);
    setApplied({ group: group.trim(), io });
  }

  function reset() {
    setGroup('');
    setIo('');
    setPageNo(0);
    setApplied({ group: '', io: '' });
  }

  function done() {
    const wasEdit = drawer?.row !== undefined;
    setDrawer(null);
    setDetail(null);
    notify(wasEdit ? '예산과목을 수정했습니다.' : '예산과목을 등록했습니다.');
    reload();
  }

  const rows = data?.items ?? [];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Tiles items={[['예산과목', data ? data.total : 0]]} />
      </section>
      <section className="box span-4">
        <h2>현재 쪽 통제 과목</h2>
        <Tiles items={[['통제', rows.filter((r) => r.isControlled === true).length]]} />
      </section>
      <section className="box span-4">
        <h2>예산과목 등록</h2>
        <Tiles items={[['현재 쪽 건수', rows.length]]} />
        <button type="button" onClick={() => setDrawer({})}>예산과목 등록</button>
      </section>
      <section className="box span-12">
        <h2>예산과목 구조</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="예산그룹">
            <TextInput value={group} onChange={setGroup} />
          </Field>
          <Field label="수입·지출 유형">
            <Select value={io} onChange={setIo} options={IO_OPTIONS} />
          </Field>
        </Filters>
        {error ? <div>{error}</div> : null}
        {loading ? <div>불러오는 중…</div> : null}
        <DataTable
          rows={rows}
          empty="등록된 예산과목이 없습니다."
          onRowClick={(r) => setDetail(r)}
          columns={[
            { key: 'budgetGroup', label: '예산그룹' },
            { key: 'ioType', label: '수입·지출 유형', render: (r) => <Badge value={r.ioType} /> },
            { key: 'itemCode', label: '예산과목 코드' },
            { key: 'itemName', label: '예산과목 명칭' },
            { key: 'parentBudgetItemId', label: '상위 예산과목', render: (r) => (r.parentBudgetItemId ? <RefName table="budget_item" role={role} value={r.parentBudgetItemId} /> : <span>-</span>) },
            { key: 'isControlled', label: '통제 여부', render: (r) => <span>{yesNo(r.isControlled)}</span> },
            { key: 'controlUnit', label: '통제 단위' },
            { key: 'isTransferable', label: '예산 전용 여부', render: (r) => <span>{yesNo(r.isTransferable)}</span> },
            { key: 'useStartDate', label: '사용 시작일', render: (r) => <DateText value={r.useStartDate} /> },
            { key: 'useEndDate', label: '사용 종료일', render: (r) => <DateText value={r.useEndDate} /> },
          ]}
        />
        <Pager page={pageNo} size={size} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
      {detail && !drawer ? (
        <Drawer title="예산과목 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['예산그룹', String(detail.budgetGroup ?? '')],
              ['수입·지출 유형', <Badge value={detail.ioType} />],
              ['상위 예산과목', detail.parentBudgetItemId ? <RefName table="budget_item" role={role} value={detail.parentBudgetItemId} /> : '-'],
              ['예산과목 코드', String(detail.itemCode ?? '')],
              ['예산과목 명칭', String(detail.itemName ?? '')],
              ['통제 여부', yesNo(detail.isControlled)],
              ['통제 단위', String(detail.controlUnit ?? '-')],
              ['예산 전용 여부', yesNo(detail.isTransferable)],
              ['사용 시작일', <DateText value={detail.useStartDate} />],
              ['사용 종료일', <DateText value={detail.useEndDate} />],
            ]}
          />
          <button type="button" onClick={() => setDrawer({ row: detail })}>수정</button>
        </Drawer>
      ) : null}
      {drawer ? (
        <Drawer title={drawer.row ? '예산과목 수정' : '예산과목 등록'} onClose={() => setDrawer(null)}>
          <ItemForm role={role} row={drawer.row} onDone={done} />
        </Drawer>
      ) : null}
    </div>
  );
}
